import { describe, expect, test } from "bun:test";
import { greet, add, slugify } from "./utils";

describe("utils", () => {
  test("greet returns greeting message", () => {
    expect(greet("Alice")).toBe("Hello, Alice!");
  });

  test("add returns sum of two numbers", () => {
    expect(add(2, 3)).toBe(5);
  });

  describe("slugify", () => {
    describe("REQ-001: Text Normalization", () => {
      test("converts uppercase letters to lowercase", () => {
        expect(slugify("HELLO World")).toBe("hello-world");
      });

      test("preserves lowercase letters", () => {
        expect(slugify("hello")).toBe("hello");
      });

      test("handles mixed case text", () => {
        expect(slugify("CamelCaseText")).toBe("camelcasetext");
      });
    });

    describe("REQ-002: Whitespace and Underscore Replacement", () => {
      test("replaces single space with hyphen", () => {
        expect(slugify("Hello World")).toBe("hello-world");
      });

      test("collapses multiple spaces into single hyphen", () => {
        expect(slugify("foo  bar")).toBe("foo-bar");
      });

      test("replaces underscores with hyphens", () => {
        expect(slugify("foo__bar")).toBe("foo-bar");
      });

      test("handles leading and trailing spaces", () => {
        expect(slugify("  foo bar  ")).toBe("foo-bar");
      });
    });

    describe("REQ-003: Special Character Removal", () => {
      test("removes punctuation", () => {
        expect(slugify("Hello, World!")).toBe("hello-world");
      });

      test("removes special characters", () => {
        expect(slugify("user@email.com")).toBe("useremailcom");
      });

      test("preserves alphanumeric characters", () => {
        expect(slugify("test123")).toBe("test123");
      });

      test("preserves hyphens", () => {
        expect(slugify("a-b")).toBe("a-b");
      });
    });

    describe("REQ-004: Hyphen Normalization", () => {
      test("collapses consecutive hyphens", () => {
        expect(slugify("a---b")).toBe("a-b");
      });

      test("collapses double hyphens", () => {
        expect(slugify("hello--world")).toBe("hello-world");
      });
    });

    describe("REQ-005: Hyphen Trimming", () => {
      test("removes leading hyphens", () => {
        expect(slugify("-hello")).toBe("hello");
      });

      test("removes trailing hyphens", () => {
        expect(slugify("world-")).toBe("world");
      });

      test("removes both leading and trailing hyphens", () => {
        expect(slugify("-hello-world-")).toBe("hello-world");
      });

      test("preserves internal hyphens", () => {
        expect(slugify("hello-world")).toBe("hello-world");
      });
    });

    describe("REQ-006: Empty Input Handling", () => {
      test("returns empty string for empty input", () => {
        expect(slugify("")).toBe("");
      });

      test("returns empty string for whitespace-only input", () => {
        expect(slugify("   ")).toBe("");
      });

      test("returns empty string for special-characters-only input", () => {
        expect(slugify("!!!")).toBe("");
      });

      test("returns empty string for hyphens-only input", () => {
        expect(slugify("---")).toBe("");
      });
    });

    describe("Test Scenarios from Requirements", () => {
      test("basic text", () => {
        expect(slugify("Hello World")).toBe("hello-world");
      });

      test("with punctuation", () => {
        expect(slugify("Hello, World!")).toBe("hello-world");
      });

      test("multiple spaces", () => {
        expect(slugify("foo  bar")).toBe("foo-bar");
      });

      test("underscores", () => {
        expect(slugify("foo__bar")).toBe("foo-bar");
      });

      test("leading/trailing spaces", () => {
        expect(slugify("  foo bar  ")).toBe("foo-bar");
      });

      test("multiple hyphens", () => {
        expect(slugify("a---b")).toBe("a-b");
      });

      test("mixed case", () => {
        expect(slugify("CamelCaseText")).toBe("camelcasetext");
      });

      test("numbers", () => {
        expect(slugify("test123")).toBe("test123");
      });

      test("special characters", () => {
        expect(slugify("user@email.com")).toBe("useremailcom");
      });

      test("empty string", () => {
        expect(slugify("")).toBe("");
      });

      test("only spaces", () => {
        expect(slugify("   ")).toBe("");
      });

      test("only special chars", () => {
        expect(slugify("!!!")).toBe("");
      });
    });
  });
});

